using Confluent.Kafka;using Microsoft.EntityFrameworkCore;using Microsoft.Extensions.Diagnostics.HealthChecks;using Microsoft.Extensions.Options;using StreamForge.Playback.Api.Data;using StreamForge.Playback.Api.Options;
namespace StreamForge.Playback.Api.Services;
public sealed class PlaybackDatabaseHealthCheck(IDbContextFactory<PlaybackDbContext> factory):IHealthCheck
{public async Task<HealthCheckResult> CheckHealthAsync(HealthCheckContext context,CancellationToken token=default){try{await using var db=await factory.CreateDbContextAsync(token);return await db.Database.CanConnectAsync(token)?HealthCheckResult.Healthy():HealthCheckResult.Unhealthy("Playback database is unavailable.");}catch(Exception ex){return HealthCheckResult.Unhealthy("Playback database check failed.",ex);}}}
public sealed class PlaybackStorageHealthCheck(IManifestStorage storage):IHealthCheck
{public async Task<HealthCheckResult> CheckHealthAsync(HealthCheckContext context,CancellationToken token=default){try{await storage.VerifyAsync(token);return HealthCheckResult.Healthy();}catch(Exception ex){return HealthCheckResult.Unhealthy("Playback storage is unavailable.",ex);}}}
public sealed class PlaybackKafkaHealthCheck(IOptions<KafkaOptions> options):IHealthCheck
{public Task<HealthCheckResult> CheckHealthAsync(HealthCheckContext context,CancellationToken token=default){try{using var admin=new AdminClientBuilder(new AdminClientConfig{BootstrapServers=options.Value.BootstrapServers}).Build();var metadata=admin.GetMetadata(options.Value.CompletedTopic,TimeSpan.FromSeconds(3));return Task.FromResult(metadata.Topics.Any(x=>x.Topic==options.Value.CompletedTopic&&x.Error.Code==ErrorCode.NoError)?HealthCheckResult.Healthy():HealthCheckResult.Unhealthy("Completion topic is unavailable."));}catch(Exception ex){return Task.FromResult(HealthCheckResult.Unhealthy("Playback Kafka is unavailable.",ex));}}}
